export const WARLOCK_COLUMNS=Object.freeze(['G','D','R','T','E','C','Y','F']);
export function wlSkillAt(key,level=1){const s=Object.hasOwn(WARLOCK_SKILLS,key)?WARLOCK_SKILLS[key]:null;if(!s)return null;const r=s.ranks[Math.max(0,Math.min(s.ranks.length-1,Math.floor(level)-1))];return polishedWarlockSkill({...s,...r,level:r.level,native:{...r},range:r.range?r.range*WARLOCK_REFERENCE.worldScale:16,radius:r.radius*WARLOCK_REFERENCE.worldScale,speed:r.speed*WARLOCK_REFERENCE.worldScale,mana:0});}
export function wlSkillPrice(hero,key){const s=WARLOCK_SKILLS[key];if(!s||s.column==='F')return Infinity;const level=hero.skillLevels?.[key]||0;return level?s.upgradeCost+s.costIncrement*Math.max(0,level-1):s.learnCost;}

